<?php
namespace App\Services\Football;
use App\Contracts\Football\FootballDataProvider;use App\Models\{Competition,Fixture,Team};use Carbon\CarbonImmutable;
final class FixtureImporter {public function __construct(private FootballDataProvider $provider){}public function importDate(string $date):int{$rows=$this->provider->fixtures($date);$count=0;foreach($rows as $row){if(!isset($row['fixture']['id'],$row['league']['id'],$row['teams']['home']['id'],$row['teams']['away']['id']))continue;$league=$row['league'];$competition=Competition::updateOrCreate(['provider_id'=>$league['id']],['name'=>$league['name']??'Unknown','country'=>$league['country']??null,'type'=>$league['type']??null,'high_variance'=>$this->isHighVariance($league['name']??'',$league['type']??'')]);$home=Team::updateOrCreate(['provider_id'=>$row['teams']['home']['id']],['name'=>$row['teams']['home']['name']??'Unknown','country'=>$league['country']??null]);$away=Team::updateOrCreate(['provider_id'=>$row['teams']['away']['id']],['name'=>$row['teams']['away']['name']??'Unknown','country'=>$league['country']??null]);Fixture::updateOrCreate(['provider_id'=>$row['fixture']['id']],['competition_id'=>$competition->id,'home_team_id'=>$home->id,'away_team_id'=>$away->id,'kickoff_at'=>CarbonImmutable::parse($row['fixture']['date']),'status'=>$row['fixture']['status']['short']??null,'home_goals'=>$row['goals']['home']??null,'away_goals'=>$row['goals']['away']??null]);$count++;}return $count;}private function isHighVariance(string $name,string $type):bool{$v=strtolower($name.' '.$type);foreach(['u17','u18','u19','u20','u21','u23','youth','reserve','reserves','friendly','friendlies'] as $needle)if(str_contains($v,$needle))return true;return false;}}
